(()=>{
 const sections=[['calendar','Календарь','admin.html','overview'],['students','Ученики','admin.html?section=students','students'],['materials','Задания и конспекты','materials.html'],['finance','Оплаты и отчёты','reports.html'],['requests','Заявки','admin.html?section=trial-requests','trial-requests'],['settings','Настройки','archive-settings.html']];
 window.mountAdminNavigation=active=>{
  let sidebar=document.querySelector('#admin-sidebar');
  if(!sidebar){sidebar=document.createElement('aside');sidebar.id='admin-sidebar';sidebar.className='admin-sidebar';const nav=document.createElement('nav');nav.setAttribute('aria-label','Разделы администратора');for(const [id,label,href,section] of sections){const link=document.createElement('a');link.href=href;link.textContent=label;link.dataset.adminNav=id;if(section)link.addEventListener('click',event=>{if(location.pathname.endsWith('/admin.html')&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&!event.altKey){event.preventDefault();window.dispatchEvent(new CustomEvent('admin-navigate',{detail:section}));toggle(false)}});nav.append(link)}const profile=document.createElement('a');profile.href='account.html?profile=1';profile.textContent='Мой профиль';profile.className='admin-sidebar-profile';const logout=document.createElement('button');logout.type='button';logout.className='admin-sidebar-logout';logout.textContent='Выйти';logout.onclick=async()=>{logout.disabled=true;try{const response=await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin',headers:{'X-Requested-With':'KrugPi','Content-Type':'application/json'},body:'{}'});if(!response.ok)throw Error('Не удалось выйти. Попробуйте ещё раз.');window.location.assign('account.html')}catch(error){logout.disabled=false;logout.textContent='Повторить выход';logout.setAttribute('aria-label',error.message);const status=document.querySelector('#status');if(status)status.textContent=error.message}};const payment=document.createElement('a');payment.href='admin.html?payment=1';payment.textContent='Пополнить баланс';payment.className='admin-sidebar-payment';payment.onclick=event=>{if(window.openAdminPayment&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&!event.altKey){event.preventDefault();toggle(false);void window.openAdminPayment()}};sidebar.append(nav,payment,profile,logout);const main=document.querySelector('main'),workspace=document.createElement('div');workspace.className='admin-workspace';main.before(workspace);workspace.append(sidebar,main);const button=document.createElement('button');button.type='button';button.id='admin-menu-toggle';button.textContent='Меню администратора';button.setAttribute('aria-controls','admin-sidebar');button.setAttribute('aria-expanded','false');button.onclick=()=>toggle(button.getAttribute('aria-expanded')!=='true');document.querySelector('main').prepend(button);document.addEventListener('keydown',event=>{if(event.key==='Escape')toggle(false)})}
  document.body.classList.add('admin-shell');if(window.openAdminPayment&&new URLSearchParams(location.search).get('payment')==='1'){const url=new URL(location.href);url.searchParams.delete('payment');history.replaceState(null,'',url);void window.openAdminPayment();}sidebar.querySelectorAll('[data-admin-nav]').forEach(link=>{if(link.dataset.adminNav===active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});
 };
 function toggle(open){document.querySelector('#admin-sidebar')?.classList.toggle('is-open',open);document.querySelector('#admin-menu-toggle')?.setAttribute('aria-expanded',String(open))}
})();
